void k1r_clockconfig(void)
{
  volatile uint32_t *reg;

  /* UART0 时钟复位控制（0xC0880000 + 0xD8）：
   * fclk sel=0 → pll1_aud_24p5(24.5MHz)，fclk_div=0，使能 pclk/fclk，释放复位。
   * ⚠️ 实测（GDB 写 THR 观察 LSR TEMT 位）：sel=0 时 THR 写生效(TEMT 1→0)，
   *   sel=1/2/3 时 THR 写不生效。故必须用 sel=0。
   */

  reg = (volatile uint32_t *)(K1R_SYSCTRL_BASE +
                              K1R_SYSCTRL_UART0_CLK_RST);

  *reg = (K1R_CLK_FCLK_SEL_24P5M << K1R_CLK_FCLK_SEL_SHIFT) |
         (0 << K1R_CLK_FCLK_DIV_SHIFT) |
         K1R_CLK_PCLK_EN |
         K1R_CLK_FCLK_EN |
         K1R_CLK_SW_RSTN;
}

input.new_string:
void k1r_clockconfig(void)
{
  volatile uint32_t *reg;

  /* 1. 使能 pll1_aud_24p5 分频时钟 gate（APBS APB_SPARE2_REG bit11）。
   *    UART0 fclk sel=0 → pll1_aud_24p5(24.576MHz)；该 gate 复位默认关，
   *    若不使能 fclk=0，UART 发送移位卡死（字符进 THR 但发不出去）。
   */

  *(volatile uint32_t *)K1R_APBS_SPARE2 |= K1R_PLL1_AUD_24P5_GATE;

  /* 2. UART0 时钟复位控制（0xC0880000 + 0xD8）：
   *    fclk sel=0 → pll1_aud_24p5，fclk_div=0，使能 pclk/fclk，释放复位。
   */

  reg = (volatile uint32_t *)(K1R_SYSCTRL_BASE +
                              K1R_SYSCTRL_UART0_CLK_RST);

  *reg = (K1R_CLK_FCLK_SEL_24P5M << K1R_CLK_FCLK_SEL_SHIFT) |
         (0 << K1R_CLK_FCLK_DIV_SHIFT) |
         K1R_CLK_PCLK_EN |
         K1R_CLK_FCLK_EN |
         K1R_CLK_SW_RSTN;
}

