  {
    /* 中断：mcause 低 12 位 = ECLIC 中断 ID */

    irq = RISCV_IRQ_ASYNC + (int)(vector & 0xfff);

    /* Acknowledge the interrupt */

    riscv_ack_irq(irq);

    /* Deliver the IRQ */

