static void u16550_send(struct uart_dev_s *dev, int ch)
{
  FAR struct u16550_s *priv = (FAR struct u16550_s *)dev->priv;

  /* Wait for the transmit holding register / FIFO to have room before
   * writing.  The serial core's uart_xmitchars() checks txready() then
   * calls send(), but on some UARTs (e.g. PXA/DW 8250 variants) there is a
   * window between reading LSR and writing THR where the FIFO can fill,
   * causing dropped bytes.  Waiting here closes that window.
   */

  while ((u16550_serialin(priv, UART_LSR_OFFSET) & UART_LSR_THRE) == 0);

  u16550_serialout(priv, UART_THR_OFFSET, (uart_datawidth_t)ch);
}

