input.new_string:
void up_enable_irq(int irq)
{
  int eclic = irq - RISCV_IRQ_ASYNC;
  uint8_t level;

  if (eclic < 0 || eclic >= K1R_NUM_ECLIC_SOURCES)
    {
      return;
    }

  /* 优先级/级别分配（ECLIC 仲裁：level 高者先）：
   *   - UART0(ECLIC 63) 给最高 level：串口 TX/RX 是字符型传输，一旦被
   *     tick 等慢速中断抢占就会丢字符（实测 banner 从 "NuttShell (NSH)"
   *     变成 "NuttSh"）。必须保证串口不被抢占。
   *   - mtimer(ECLIC 7) 给最低非 0 level：tick 允许被串口抢占/延迟，
   *     但不能为 0（level=0 等同关闭）。 */

  if (eclic == 63)          /* UART0 */
    {
      level = g_max_level;
    }
  else if (eclic == 7)      /* mtimer */
    {
      level = 1;
    }
  else
    {
      level = g_max_level;
    }

  k1r_eclic_set_intctl(eclic, level, 0);
  K1R_ECLIC_CTRL(eclic)->intie = 1;
}

