/* PXA UART 使能：
 * IER = UUE(0x40) | RLSI(0x04) | RTOIE(0x20)：RLSI+RTOIE 是 PXA RDA
 *   中断触发的前提（GDB 实测：仅 UUE+ERBFI 时 IIR 恒 NO_INT、RX 中断
 *   不上报；IER=0x65=RDA|RLSI|RTOIE|UUE 与 Linux pxa_k1x 一致时 RDA
 *   中断正常产生）。16550 驱动 attach 时对 IER 读-改-写，会保留这些
 *   预置位，之后再按需叠加 ERBFI(接收数据可用)/ETBEI(发送保持寄存器空)。
 * MCR = OUT2(0x08)   ← 关键：发送使能，漏掉则 THR 写不生效
 * FCR = 0x07         ← enable + clear RCVR + clear XMIT
 */

K1R_UART_REG(base, K1R_UART_IER_DLM) =
    K1R_UART_IER_UUE | K1R_UART_IER_RLSI | K1R_UART_IER_RTOIE;
K1R_UART_REG(base, K1R_UART_MCR)     = K1R_UART_MCR_OUT2;
K1R_UART_REG(base, K1R_UART_FCR_IIR) = 0x07;

